{
  "incident_detected": false,
  "root_cause_hypothesis": "No convincing evidence of a new onboarding break. April's organic activation is within historical monthly variation; March was relatively strong. KYC approval improved slightly, while the decline was concentrated after approval, and equal-window activation shows a smaller drop.",
  "supporting_metrics": [
    {
      "name": "organic signup activation rate, March versus April 2026",
      "baseline_value": 0.420664,
      "anomaly_value": 0.394461,
      "unit": "fraction",
      "sql": "SELECT signup_month, sum(n_activated)::DOUBLE/sum(n_signups) activation_rate FROM agg_funnel_monthly WHERE channel='organic' AND signup_month IN ('2026-03-01','2026-04-01') GROUP BY 1 ORDER BY 1"
    },
    {
      "name": "organic historical monthly activation mean and standard deviation, January 2024–February 2026",
      "baseline_value": 0.406547,
      "anomaly_value": 0.013183,
      "unit": "fraction",
      "sql": "WITH m AS (SELECT signup_month, sum(n_activated)::DOUBLE/sum(n_signups) rate FROM agg_funnel_monthly WHERE channel='organic' AND signup_month < '2026-05-01' GROUP BY 1), d AS (SELECT *, rate-lag(rate) OVER (ORDER BY signup_month) delta FROM m) SELECT avg(rate) FILTER(WHERE signup_month<'2026-03-01') historical_mean, stddev_samp(rate) FILTER(WHERE signup_month<'2026-03-01') historical_monthly_sd, stddev_samp(delta) FILTER(WHERE signup_month<'2026-03-01') historical_mom_sd, (SELECT rate FROM m WHERE signup_month='2026-04-01')-(SELECT rate FROM m WHERE signup_month='2026-03-01') march_april_delta FROM d"
    },
    {
      "name": "organic activation historical month-over-month standard deviation versus March–April change",
      "baseline_value": 0.014961,
      "anomaly_value": -0.026203,
      "unit": "fraction",
      "sql": "WITH m AS (SELECT signup_month, sum(n_activated)::DOUBLE/sum(n_signups) rate FROM agg_funnel_monthly WHERE channel='organic' AND signup_month < '2026-05-01' GROUP BY 1), d AS (SELECT *, rate-lag(rate) OVER (ORDER BY signup_month) delta FROM m) SELECT stddev_samp(delta) FILTER(WHERE signup_month<'2026-03-01') historical_mom_sd, (SELECT rate FROM m WHERE signup_month='2026-04-01')-(SELECT rate FROM m WHERE signup_month='2026-03-01') march_april_delta FROM d"
    },
    {
      "name": "organic March–April activation two-proportion test p-value",
      "baseline_value": null,
      "anomaly_value": 0.0399,
      "unit": "fraction",
      "sql": "calculate_uplift_or_stats(metric_slice={analysis:'two_proportion_test',platform:null,doc_type:null,channel:null,segment_by:null,k_a:1254,n_a:2981,k_b:1168,n_b:2961})"
    },
    {
      "name": "organic document submission to KYC approval rate, March versus April 2026",
      "baseline_value": 0.859347,
      "anomaly_value": 0.863553,
      "unit": "fraction",
      "sql": "SELECT signup_month, sum(n_kyc_approved)::DOUBLE/sum(n_doc_submitted) approval_rate FROM agg_funnel_monthly WHERE channel='organic' AND signup_month >= '2025-10-01' GROUP BY signup_month ORDER BY signup_month"
    },
    {
      "name": "organic activation within 30 days of signup, March versus April 2026",
      "baseline_value": 0.398524,
      "anomaly_value": 0.379264,
      "unit": "fraction",
      "sql": "SELECT signup_month, count(*) n, avg(CASE WHEN is_activated AND activation_ts <= signup_ts + INTERVAL '14 days' THEN 1.0 ELSE 0 END) activation_14d, avg(CASE WHEN is_activated AND activation_ts <= signup_ts + INTERVAL '30 days' THEN 1.0 ELSE 0 END) activation_30d FROM dim_users WHERE channel='organic' AND signup_month >= '2026-01-01' AND signup_month < '2026-05-01' GROUP BY 1 ORDER BY 1"
    }
  ],
  "recommended_action": "NO_ACTION_NOISE",
  "reasoning_summary": "Organic activation fell from 0.420664 to 0.394461, but April remains close to the historical mean of 0.406547, with monthly standard deviation 0.013183. The pairwise test gives p=0.0399, but historical month-over-month standard deviation is 0.014961, so this isolated change is not compelling evidence of an incident. KYC approval increased from 0.859347 to 0.863553, and equal-window activation fell less sharply, from 0.398524 to 0.379264. Do not roll back a release; monitor subsequent mature cohorts and post-approval conversion for a persistent decline."
}
